package com.smartparking.dao;
import com.smartparking.database.DBConnection;import com.smartparking.model.*;import java.sql.*;import java.time.*;import java.util.*;
public class ParkingTicketDAO { public void insert(Connection c,ParkingTicket t)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO parking_tickets(ticket_id,registration_number,slot_id,entry_time,status) VALUES(?,?,?,?, 'ACTIVE')")){p.setString(1,t.id());p.setString(2,t.vehicle().getRegistrationNumber());p.setString(3,t.slot().getId());p.setTimestamp(4,Timestamp.valueOf(t.entryTime()));p.executeUpdate();}} public Optional<ParkingTicket> active(String r)throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT t.*,s.floor_number,s.slot_size,s.distance_from_entrance,v.owner_name,v.vehicle_type FROM parking_tickets t JOIN parking_slots s ON s.slot_id=t.slot_id JOIN vehicles v ON v.registration_number=t.registration_number WHERE t.registration_number=? AND t.status='ACTIVE'")){p.setString(1,r);try(ResultSet x=p.executeQuery()){if(!x.next())return Optional.empty();Vehicle v=vehicle(x);ParkingSlot s=new ParkingSlot(x.getString("slot_id"),x.getInt("floor_number"),x.getInt("slot_size"),x.getInt("distance_from_entrance"));s.occupy();return Optional.of(new ParkingTicket(x.getString("ticket_id"),v,s,x.getTimestamp("entry_time").toLocalDateTime(),null,null,null,null));}}} public void close(Connection c,ParkingTicket t,LocalDateTime at,java.math.BigDecimal amount)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE parking_tickets SET exit_time=?,amount=?,status='CLOSED' WHERE ticket_id=? AND status='ACTIVE'")){p.setTimestamp(1,Timestamp.valueOf(at));p.setBigDecimal(2,amount);p.setString(3,t.id());if(p.executeUpdate()!=1)throw new SQLException("Ticket is not active");}} static Vehicle vehicle(ResultSet x)throws SQLException{return switch(x.getString("vehicle_type")){case "CAR"->new Car(x.getString("registration_number"),x.getString("owner_name"));case "BIKE"->new Bike(x.getString("registration_number"),x.getString("owner_name"));default->new Truck(x.getString("registration_number"),x.getString("owner_name"));};} }
